import{c as t,Q as a,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse(`{"title":"Please don't implement a 'company brain' and expect a learning loop","description":"","frontmatter":{"url":"https://x.com/sethrosen/status/2066534763511316540","title":"Please don't implement a 'company brain' and expect a learning loop","author":"Seth Rosen","archived":"2026-06-16T00:00:00.000Z","handle":"@sethrosen","published":"2026-06-15T00:00:00.000Z","stats":"120 likes · 11 retweets · 423 bookmarks · 26694 views","tags":["learning-loop","minimum-viable-context","stewardship-pattern","organizational-ai","ai-strategy"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-15-@sethrosen-316540.md","filePath":"research/tweets/2026-06-15-@sethrosen-316540.md","lastUpdated":1785909234000}`),s={name:"research/tweets/2026-06-15-@sethrosen-316540.md"};function r(i,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="please-don-t-implement-a-company-brain-and-expect-a-learning-loop-—-sethrosen" tabindex="-1">Please don&#39;t implement a &quot;company brain&quot; and expect a learning loop — @sethrosen <a class="header-anchor" href="#please-don-t-implement-a-company-brain-and-expect-a-learning-loop-—-sethrosen" aria-label="Permalink to &quot;Please don&#39;t implement a &quot;company brain&quot; and expect a learning loop — @sethrosen&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/sethrosen/status/2066534763511316540" target="_blank" rel="noreferrer">https://x.com/sethrosen/status/2066534763511316540</a><strong>作者</strong>：Seth Rosen（@sethrosen） <strong>發布日期</strong>：2026-06-15 <strong>收錄日期</strong>：2026-06-16 <strong>類型</strong>：Twitter Article <strong>統計</strong>：120 likes · 11 retweets · 423 bookmarks · 26694 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Satya&#39;s piece is rightly going viral. He&#39;s connecting two things, human capital and token capital, through a learning loop: how humans steer AI, how AI makes humans smarter, and how the whole thing compounds. We&#39;ve been researching and building exactly this for nine months. The learning loop is your long-horizon AI strategy. Without it, AI is incredible in the moment but decays silently over the long run. Long-horizon AI work spans far beyond a Codex or Claude session. It&#39;s the work where every employee wakes up each morning iterating on the overall goal of their team and the organization. Your long-horizon learning loop has four properties.</p><ol><li>Minimum Viable Context. Seed the system with the judgment only your company has, not everything it has ever said.</li><li>Structured, introspectable, multiplayer. Everyone and every agent builds on the same shared foundation, and intermediate decisions can be traced and judged.</li><li>Executable. Once the work is visible, agents can operate on it directly.</li><li>Compounding. It measurably gets better the more it&#39;s used. The opposite of AI decay. Start from Minimum Viable Context Context is your most precious asset. It&#39;s also your most dangerous one. For that reason, do not pull the whole company into a shared knowledge graph. Don&#39;t do the full &quot;company brain&quot; thing. You start from a curated set of shared knowledge, and you spend real time curating it down as much as possible. Start with the decisions where your company&#39;s expertise actually matters: strategy, product tradeoffs, customer understanding, risk assessment, market interpretation, sales judgment, engineering architecture, operational playbooks. The opportunity is not to automate generic work. It is to find the places where human capital creates differentiated judgment. Humans can filter context against their own understanding of the world, built through meetings, offsites, and deep work. AI can&#39;t come to your offsite. You need to build clean context the same way you onboard a new employee. You wouldn&#39;t hand a new hire access to everything on day one and tell them to just start working. This is the start of your shared system. Make the work structured and multiplayer Once everyone and every agent works from the same Minimum Viable Context, all future work gets built and evaluated against it. That means turning your Minimum Viable Context into assumptions, source context, intermediate reasoning, examples, constraints, rubrics, decisions, and outputs. Do not bury the company&#39;s learning inside prompts, chats, or individual memories. Make the reasoning visible, editable, reusable, and shared across people, agents, and teams. Make the system executable Once the work is visible, agents can operate on it. Structure the artifacts into repeatable circuits with dependencies, inputs, intermediate outputs, and final deliverables. Now AI is not just answering questions. It is participating in a governed system of work that can be replayed, revised, inspected, and improved. So much of organizational work is interdependent: Product, Engineering, Marketing, and Support all lean on each other&#39;s output. An important artifact usually gets used downstream across many areas, well beyond the team that produced it. If AI is only used to produce final artifacts, a marketing brief, a piece of code, a support article, then all of the intermediate work behind them gets redone by each department. These intermediate artifacts are also introspectable. Humans and AI can see how a decision or document was actually produced, which is foundational to the learning loop. Conceptually, this is very similar to data engineering, where tools like dbt are used to model organizational business logic. There are a lot of patterns to share here. Everything inherently compounds We call this the stewardship pattern, and it&#39;s how the system compounds. Everyone can keep their own harness, Claude, Codex, whatever they like. The contract is that every session leaves the shared structure in better shape than it started, by updating structure, adding it where it&#39;s missing, and introspecting the artifacts. That is how personal harnesses compound across the org. Without that contract, they just fragment it. This is a human problem and an AI problem at the same time. When a foundational principle is added or changed, the explicit structure knows exactly what to update and what no longer aligns. That is the opposite of AI decay. Then change what you reward You must reward the people who make this happen. Most organizations have focused on procuring AI tools, which produces a small set of elite early-adopter employees. If every employee has their own chat, their own memories, and their own files, a few of them get sharper in private. The organization gets nothing. You may even get acceleration in conflicting directions. This is &quot;AI hero ball,&quot; and nobody wins championships that way. Ignore AI output that doesn&#39;t use or improve the organizational system. Reward the people who build the system, and the ones who use it.</li></ol><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：不要建「公司大腦」（全知識圖）——從 Minimum Viable Context 出發，用 stewardship pattern 讓每次 AI session 更新共享結構，才是讓組織 AI 能力真正複利增長的學習迴路。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>MVC 優於「公司大腦」</strong>：不把所有知識塞入共享知識圖，精挑人類判斷力真正有差異化的部分（策略、產品取捨、客戶洞察、風險評估、工程架構等），像 onboarding 新員工一樣建立乾淨 context</li><li><strong>學習迴路四特性</strong>：Minimum Viable Context（精選差異化判斷）+ 結構化/可追蹤/多人協作 + Executable（agents 可直接操作 artifacts）+ Compounding（使用越多越好，與 AI decay 相反）</li><li><strong>Stewardship Pattern</strong>：每個 AI session 的契約是把共享結構留在比開始時更好的狀態（更新、補缺、檢視），個人 harness 的成長必須轉化為組織複利，否則只是碎片化</li><li><strong>中間 artifacts 必須可見</strong>：別讓中間推理（assumptions、intermediate reasoning、decisions）埋在 prompt 或個人記憶，轉為可共享/可重用/可追蹤的結構（類似 dbt 對資料工程的作用）</li><li><strong>獎勵機制必須對齊</strong>：「AI hero ball」（少數人在私下變強，組織零收益）是失敗模式；必須獎勵建立和使用組織系統的人，忽略不使用或不改進系統的 AI 輸出</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><strong>Minimum Viable Context (MVC)</strong>：從公司差異化判斷力精選最小必要 context</li><li><strong>Stewardship Pattern</strong>：每次 session 更新共享結構的契約</li><li><strong>dbt 比喻</strong>：中間 artifacts 的可追蹤/可重用設計，類似資料工程的 data modeling</li><li><strong>Long-horizon AI work</strong>：跨越單一 Codex/Claude session 的工作，是 AI 策略的真正戰場</li><li><strong>AI decay</strong>：未建立學習迴路時，AI 長期效益靜默衰退的現象</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>Stewardship pattern 的執行機制未說明</strong>：「每次 session 更新共享結構」是好的設計哲學，但需要 incentive 設計 + 技術機制（如 CI/CD gate、session hooks），文章未提供具體實作路徑</li><li><strong>與 cc-workspace 哲學高度相符</strong>：MEMORY.md + skills/ + 跨 session 知識累積正是單人層次的 stewardship pattern 實踐，本文將其推廣到組織層次，是有力的驗證</li><li><strong>Intermediate artifacts 設計的判斷標準缺失</strong>：dbt 比喻啟發性強，但「哪些中間決策應結構化」vs「留在 chat」是實際執行的關鍵挑戰，未深入</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>Stewardship pattern 直接對應 cc-workspace 的 MEMORY.md + skills/ 設計哲學</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>&quot;Company brain vs MVC&quot; 對比、stewardship pattern 契約、dbt 跨領域比喻均有洞見</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>概念論述為主，「九個月研究」未說明具體發現，無量化數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>Intermediate artifacts / dbt 比喻提供技術方向，但實作層次較淺</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>四特性學習迴路、stewardship pattern 跨組織規模通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.1/10</strong></td><td>8×0.3+8×0.2+5×0.2+6×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Minimum Viable Context + stewardship pattern 是組織層次 AI 學習迴路的通用原則，強化 cc-workspace 的跨 session 知識累積設計哲學。</p>',19)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
